INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bb0115d2-fa71-4861-a6ea-2f15e828ab06', '父の死と同日に、アポロ11号が月面着陸に成功した。', 'Di hari yang sama dengan kematian ayah saya, Apollo 11 berhasil mendarat di permukaan bulan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5705e2fb-70a5-4e67-a508-1ede7d386b22', 'vocabulary', '多い', '多い', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari banyak? Jumlahnya juga banyak (atau bisa dibilang banyak). Ngomong-ngomong, ada banyak sekali kanji yang harus dipelajari ya?', 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari banyak? Jumlahnya juga banyak (atau bisa dibilang banyak). Ngomong-ngomong, ada banyak sekali kanji yang harus dipelajari ya?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
