INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5705e2fb-70a5-4e67-a508-1ede7d386b22', 'このりょうりは多すぎます。', 'Ada terlalu banyak makanan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5705e2fb-70a5-4e67-a508-1ede7d386b22', '「自分は正しい」とおもいこんでいる人は多い。', 'Ada banyak orang yang sangat yakin bahwa mereka benar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5705e2fb-70a5-4e67-a508-1ede7d386b22', '電車にはとても多くの乗客が乗っていたので、眠ることはできなかったが、大声で歌うことはできた。', 'Aku tidak bisa tidur karena terlalu banyak orang di kereta, jadi aku hanya bernyanyi dengan keras.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('995d671a-15a9-4f66-8ca4-446712df9135', 'vocabulary', '多分', '多分', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda memiliki banyak bagian. Lihatlah semuanya. Anda harus memilih salah satu bagian. Anda tidak dapat memutuskan mana yang Anda inginkan. Yang ini? Mungkin. Bagaimana dengan yang ini? Hmm, mungkin itu juga.', 'Anda memiliki banyak bagian. Lihatlah semuanya. Anda harus memilih salah satu bagian. Anda tidak dapat memutuskan mana yang Anda inginkan. Yang ini? Mungkin. Bagaimana dengan yang ini? Hmm, mungkin itu juga.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('995d671a-15a9-4f66-8ca4-446712df9135', 'Mungkin', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('995d671a-15a9-4f66-8ca4-446712df9135', 'Perhaps', false) ON CONFLICT DO NOTHING;
