INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('995d671a-15a9-4f66-8ca4-446712df9135', 'かさは、多分外にあります。', 'Mungkin payungnya ada di luar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('995d671a-15a9-4f66-8ca4-446712df9135', '多分、レイヤーさんなのかもしれないよ。', 'Mungkin, dia adalah seorang cosplayer.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('995d671a-15a9-4f66-8ca4-446712df9135', '明日の夜は多分雪になるから、雪だるまを作ろう。', 'Mungkin besok akan turun salju, jadi mari kita membuat manusia salju.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3cad3622-3750-4983-977f-27442b6d6b5e', 'vocabulary', '考え', '考え', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Ini adalah versi kata benda dari pemikiran. Apa itu "berpikir"? Itu sebuah pemikiran.', 'Ini adalah versi kata benda dari pemikiran. Apa itu "berpikir"? Itu sebuah pemikiran.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3cad3622-3750-4983-977f-27442b6d6b5e', 'Pikir', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('3cad3622-3750-4983-977f-27442b6d6b5e', 'A Thought', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('3cad3622-3750-4983-977f-27442b6d6b5e', 'かんがえ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3cad3622-3750-4983-977f-27442b6d6b5e', 'いつも自分の考えを上手くせつめいできません。', 'Saya tidak pernah bisa menjelaskan pikiran saya dengan baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3cad3622-3750-4983-977f-27442b6d6b5e', 'あなたの考えはあますぎます。', 'Pikiran Anda terlalu optimis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3cad3622-3750-4983-977f-27442b6d6b5e', 'あなたの考えを百円で買わせてもらえませんか？', 'Bisakah saya membeli pemikiran Anda seharga 100 yen?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('aa53743f-e222-4728-8cca-f184ed98148d', 'vocabulary', '考える', '考える', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berpikir, jadi versi verbanya adalah memikirkan atau mempertimbangkan. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('aa53743f-e222-4728-8cca-f184ed98148d', 'Untuk Dipikirkan Tentang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('aa53743f-e222-4728-8cca-f184ed98148d', 'To Consider', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('aa53743f-e222-4728-8cca-f184ed98148d', 'To Give Thought', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('aa53743f-e222-4728-8cca-f184ed98148d', 'かんがえる', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa53743f-e222-4728-8cca-f184ed98148d', '少し考えさせてください。', 'Tolong izinkan saya memikirkannya sebentar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa53743f-e222-4728-8cca-f184ed98148d', '考えるな！かんじろ！', 'Jangan berpikir. Rasakan saja!') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('aa53743f-e222-4728-8cca-f184ed98148d', '私の娘は、もしタイタニック号が沈まなければ、みんなその代わりにディズニーランドに行くことができて、もっといい映画になったのにと考える。', 'Putri saya percaya bahwa film Titanic akan lebih baik jika kapalnya tidak pernah tenggelam dan semua orang pergi ke Disneyland.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('68631048-f426-4e6f-894d-34a349e82d8c', 'vocabulary', '考え方', '考え方', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Cara berpikirnya adalah cara berpikir seseorang. Itu sebabnya kata ini berarti cara berpikir.', 'Cara berpikirnya adalah cara berpikir seseorang. Itu sebabnya kata ini berarti cara berpikir.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('68631048-f426-4e6f-894d-34a349e82d8c', 'Cara Berpikir', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('68631048-f426-4e6f-894d-34a349e82d8c', 'Thought Process', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('68631048-f426-4e6f-894d-34a349e82d8c', 'かんがえかた', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68631048-f426-4e6f-894d-34a349e82d8c', '考え方は、人それぞれです。', 'Orang mempunyai cara berpikirnya masing-masing.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68631048-f426-4e6f-894d-34a349e82d8c', 'そもそも、父と母は考え方がまったくちがうんです。', 'Proses berpikir ayah dan ibu saya pada awalnya sangat berbeda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('68631048-f426-4e6f-894d-34a349e82d8c', '自分のことを悪い人間だと思うのは、もし自分が実際に悪女だったとしても、良くない考え方です。', 'Meskipun Anda benar-benar wanita yang buruk, memikirkan hal buruk tentang diri sendiri tetap bukanlah cara berpikir yang sehat.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e2a56be5-70e1-4a74-a5db-586352f0ca2a', 'vocabulary', '肉', '肉', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e2a56be5-70e1-4a74-a5db-586352f0ca2a', 'Daging', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e2a56be5-70e1-4a74-a5db-586352f0ca2a', 'にく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2a56be5-70e1-4a74-a5db-586352f0ca2a', '水よう日は、肉がやすいです。', 'Pada hari Rabu, harga daging murah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2a56be5-70e1-4a74-a5db-586352f0ca2a', '牛肉とぶた肉ととり肉の中ではどれが一ばんすきですか。', 'Di antara daging sapi, babi, dan ayam, daging manakah yang paling Anda sukai?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e2a56be5-70e1-4a74-a5db-586352f0ca2a', 'お肉は、二枚の食パンに挟まれる、もっとも重要な具材です。', 'Daging merupakan komponen terpenting di antara dua potong roti.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e1514a84-9b8b-48d7-925f-9d9c9468961d', 'vocabulary', '牛肉', '牛肉', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Apa yang Anda sebut daging sapi? Anda menyebutnya daging sapi (makan malamnya apa?).', 'Apa yang Anda sebut daging sapi? Anda menyebutnya daging sapi (makan malamnya apa?).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e1514a84-9b8b-48d7-925f-9d9c9468961d', 'Daging sapi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e1514a84-9b8b-48d7-925f-9d9c9468961d', 'ぎゅうにく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e1514a84-9b8b-48d7-925f-9d9c9468961d', 'いえのちかくのえきででんしゃをおりて、スーパーに牛肉をかいに行きました。', 'Saya turun dari kereta di stasiun dekat rumah saya dan pergi ke toko kelontong untuk membeli daging sapi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e1514a84-9b8b-48d7-925f-9d9c9468961d', '去年、えいこくさん牛肉のゆ入がさいかいされました。', 'Tahun lalu, impor daging sapi Inggris dilanjutkan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e1514a84-9b8b-48d7-925f-9d9c9468961d', '牛肉はありえないくらい生焼けだ。この牛肉のせいで今夜はキッチンの悪夢を見ることになりそうだ。', 'Daging sapinya kurang matang. Saya mungkin mengalami mimpi buruk di dapur malam ini karena ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ca73d80-942b-4913-af7b-9211d6fe9348', 'vocabulary', '自分', '自分', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda memiliki bagian diri Anda. Bagian dari diri Anda adalah Anda. Ini adalah diri sendiri. Ini adalah diriku sendiri. Tunggu, siapa bagian diriku ini? Anda tidak yakin... tunggu, tidak, itu saya sendiri. Apakah itu? Jadilah sedikit psikotik sejenak saat Anda mencoba mengingat kosakata ini.', 'Anda memiliki bagian diri Anda. Bagian dari diri Anda adalah Anda. Ini adalah diri sendiri. Ini adalah diriku sendiri. Tunggu, siapa bagian diriku ini? Anda tidak yakin... tunggu, tidak, itu saya sendiri. Apakah itu? Jadilah sedikit psikotik sejenak saat Anda mencoba mengingat kosakata ini.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7ca73d80-942b-4913-af7b-9211d6fe9348', 'Diri sendiri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7ca73d80-942b-4913-af7b-9211d6fe9348', 'Myself', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7ca73d80-942b-4913-af7b-9211d6fe9348', 'Self', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7ca73d80-942b-4913-af7b-9211d6fe9348', 'じぶん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ca73d80-942b-4913-af7b-9211d6fe9348', 'ちゃんと自分でしゅくだいをしました。', 'Saya menyelesaikan pekerjaan rumah saya sendiri dengan sempurna.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ca73d80-942b-4913-af7b-9211d6fe9348', '自分に自しんがないとえらべない色だよね。', 'Itu warna yang hanya bisa kamu pilih jika kamu percaya diri dengan dirimu sendiri, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ca73d80-942b-4913-af7b-9211d6fe9348', 'もちろん私は自分と話しますよ。だって、時には専門家の意見が必要ですもの。', 'Tentu saja aku berbicara pada diriku sendiri. Terkadang saya membutuhkan nasihat ahli.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('ac83ab1f-416c-4db5-bb29-d1710df75c5c', 'vocabulary', '自立', '自立', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda mampu berdiri dengan menggunakan diri Anda sendiri. Tidak ada yang membantu Anda. Tidak ada yang menahanmu. Ini adalah kemerdekaan Anda!', 'Anda mampu berdiri dengan menggunakan diri Anda sendiri. Tidak ada yang membantu Anda. Tidak ada yang menahanmu. Ini adalah kemerdekaan Anda!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ac83ab1f-416c-4db5-bb29-d1710df75c5c', 'Kemerdekaan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ac83ab1f-416c-4db5-bb29-d1710df75c5c', 'Self Reliance', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ac83ab1f-416c-4db5-bb29-d1710df75c5c', 'Independent', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('ac83ab1f-416c-4db5-bb29-d1710df75c5c', 'じりつ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ac83ab1f-416c-4db5-bb29-d1710df75c5c', 'むすこもようやく自立しはじめました。', 'Anak saya akhirnya mulai mandiri.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ac83ab1f-416c-4db5-bb29-d1710df75c5c', '自立しんけいしっちょうしょうがなおったら、自立しようとおもっています。', 'Saya berpikir untuk hidup mandiri, jika saya pulih dari disfungsi otonom.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ac83ab1f-416c-4db5-bb29-d1710df75c5c', 'もしあなたが強くて自立した日本人女性で、男なんて必要ないというなら、これをシェアしてください。', 'Bagikan ini jika Anda adalah wanita Jepang yang kuat dan mandiri yang tidak membutuhkan pria.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('7ab0218f-5bc2-46e6-8f85-ce0de46c16ae', 'vocabulary', '色', '色', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
