INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bee3cbdc-8467-4d9e-a7e8-a1e18d3d9946', 'おふろに入ると、はじめに体をあらいます。', 'Saat aku mandi, aku membasuh badanku terlebih dahulu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bee3cbdc-8467-4d9e-a7e8-a1e18d3d9946', 'ジャマルって何でそんなに体がやわらかいの？', 'Jamal, kenapa tubuhmu begitu fleksibel?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bee3cbdc-8467-4d9e-a7e8-a1e18d3d9946', 'なぜだか、体中がかゆいんだ。', 'Seluruh tubuh saya sangat gatal karena suatu alasan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a68839af-8c41-4538-bb27-7a5e4ff66017', 'vocabulary', '体力', '体力', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda memiliki kekuatan tubuh Anda. Ini hanyalah cara lain untuk mengatakan kekuatan fisik. Hati-hati, jika Anda menggunakan terlalu banyak kekuatan fisik, Anda mungkin kehabisan stamina dan daya tahan fisik sepenuhnya! Mereka terikat bersama, jadi pastikan untuk mengatur kecepatan Anda sendiri.', 'Anda memiliki kekuatan tubuh Anda. Ini hanyalah cara lain untuk mengatakan kekuatan fisik. Hati-hati, jika Anda menggunakan terlalu banyak kekuatan fisik, Anda mungkin kehabisan stamina dan daya tahan fisik sepenuhnya! Mereka terikat bersama, jadi pastikan untuk mengatur kecepatan Anda sendiri.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
