INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ec47f2a-ece0-4930-b9de-3c3eb36a862f', 'この作文を、中川先生にわたしてください。', 'Tolong serahkan esai ini kepada profesor Nakagawa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0ec47f2a-ece0-4930-b9de-3c3eb36a862f', '作文のテストで百てんをもらいました。', 'Saya mendapat nilai 100 persen pada ujian esai.') ON CONFLICT DO NOTHING;
