INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('02aa7bed-ddcb-4adf-8c45-ad1872b7c0ce', 'vocabulary', '作用', '作用', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Saat Anda membuat tugas, Anda mencari efek dan/atau tindakan tertentu. Tugas apa yang dapat Anda lakukan saat ini untuk mendapatkan efek mempelajari lebih banyak kanji?', 'Saat Anda membuat tugas, Anda mencari efek dan/atau tindakan tertentu. Tugas apa yang dapat Anda lakukan saat ini untuk mendapatkan efek mempelajari lebih banyak kanji?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
