INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('02aa7bed-ddcb-4adf-8c45-ad1872b7c0ce', 'アルコールの作用をおしえてください。', 'Ajari saya tentang efek alkohol.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('02aa7bed-ddcb-4adf-8c45-ad1872b7c0ce', '今日、学こうで、作用・はん作用のほうそくを学んだ。', 'Saya mempelajari hukum ketiga Newton tentang gerak di sekolah hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('02aa7bed-ddcb-4adf-8c45-ad1872b7c0ce', 'このケーキの味がする薬には、副作用はありませんか？', 'Apakah obat rasa kue ini ada efek sampingnya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e412bb0f-4ca9-404d-941f-86c40ac97493', 'vocabulary', '工作', '工作', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Apa yang dimaksud dengan "industri pembuatan"? Tentu saja, itu terjadi ketika Anda rajin membuat sesuatu. Itu hanya bisa berupa kerajinan tangan atau kerajinan tangan! Hal ini juga dapat berarti melakukan manuver, dalam artian melakukan sesuatu di belakang layar.', 'Apa yang dimaksud dengan "industri pembuatan"? Tentu saja, itu terjadi ketika Anda rajin membuat sesuatu. Itu hanya bisa berupa kerajinan tangan atau kerajinan tangan! Hal ini juga dapat berarti melakukan manuver, dalam artian melakukan sesuatu di belakang layar.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
