INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('bf802987-d5cd-483e-8f82-9af73de396fb', 'いつもありがとうってえいごで何て言うの？', 'Bagaimana cara mengucapkan, "Terima kasih selalu" dalam bahasa Inggris?') ON CONFLICT DO NOTHING;
