INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('193df329-4267-4464-8e76-dafb11f86ff4', 'コウイチはマインクラフトに広大な土地をもっている。', 'Koichi memiliki sebidang tanah yang luas di Minecraft.') ON CONFLICT DO NOTHING;
