INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2c20b5b7-e762-4667-b1da-aa361eb0ffa4', 'そして、でん車は安い方がいいです。', 'Selain itu, kereta murah lebih baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2c20b5b7-e762-4667-b1da-aa361eb0ffa4', 'タイのぶっかはアメリカよりも安いです。', 'Harga di Thailand lebih murah dibandingkan Amerika.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2c20b5b7-e762-4667-b1da-aa361eb0ffa4', 'アパートの屋根から投げて粉々になるのを見てみたかったので、昨日すごく安いラジオを買った。', 'Saya membeli radio yang sangat murah kemarin supaya saya bisa membuangnya dari atap apartemen saya dan melihatnya pecah.') ON CONFLICT DO NOTHING;
