INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cf16c4a0-d77d-450d-967b-491cff3fc078', 'これで安心です。', 'Itu melegakan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cf16c4a0-d77d-450d-967b-491cff3fc078', 'あの子は次の行どうがよそくできないから、安心できないのよね。', 'Saya tidak pernah tahu apa yang akan dilakukan anak itu selanjutnya, jadi saya tidak bisa tenang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cf16c4a0-d77d-450d-967b-491cff3fc078', 'お父さんの癌が無くなったことを聞いて、とても安心した。', 'Saya merasa sangat lega sekarang karena saya tahu ayah saya tidak lagi menderita kanker.') ON CONFLICT DO NOTHING;
