INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3029f190-3702-468c-878c-bec340270ff8', '先生が教室に入ってきたと同時に、しぎょうのチャイムがなりました。', 'Pada saat yang sama guru masuk ke dalam kelas, bel berbunyi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3029f190-3702-468c-878c-bec340270ff8', 'でん子レンジとトースターを同時につかったから、ブレーカーがおちちゃったんだ。', 'Saya menggunakan microwave dan pemanggang roti secara bersamaan, dan pemutus arusnya terputus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('3029f190-3702-468c-878c-bec340270ff8', '「今日はよくできましたね。それではまた来週同じ時間に。」と、コスプレのプロとアニメオタクが同時に言った。', '"Pelajaran yang bagus hari ini. Sampai jumpa minggu depan," kata cosplayer profesional dan kutu buku anime secara bersamaan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fa570062-9250-4e52-bd17-a4e0315dd45f', 'vocabulary', '心身', '心身', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Secara teknis kanji ini adalah hati dan seseorang, tapi pikirkanlah seperti ini. Dari mana datangnya segala sesuatu dalam diri seseorang? Jantung! Itu membuat segala sesuatunya berjalan dengan memompa darah, memberikan landasan bagi pikiran dan tubuh yang baik.', 'Secara teknis kanji ini adalah hati dan seseorang, tapi pikirkanlah seperti ini. Dari mana datangnya segala sesuatu dalam diri seseorang? Jantung! Itu membuat segala sesuatunya berjalan dengan memompa darah, memberikan landasan bagi pikiran dan tubuh yang baik.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
