INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee1ffb48-7c55-4f55-aa54-8fe8defbb3fa', '二人はふた子だが、いつもそれぞれ別々なことを考えてる。', 'Mereka kembar, tapi mereka berpikir secara terpisah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee1ffb48-7c55-4f55-aa54-8fe8defbb3fa', 'サボテンとは別々にしてうえて下さい。', 'Silakan tanam ini secara terpisah dari kaktus.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ee1ffb48-7c55-4f55-aa54-8fe8defbb3fa', '「私達、本当に別々の道を進まなきゃいけないの？」「ああ。でもまたすぐ会えるさ。」', '"Sekarang apakah kita benar-benar harus berpisah?" "Ya, tapi aku yakin kita akan segera bertemu lagi."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('38924381-e7e5-4fa8-baf3-b4ff53b871a1', 'vocabulary', '小文字', '小文字', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Anda tahu bahwa 文字 berarti "huruf". Jadi, apa itu "huruf kecil"? Itu akan menjadi huruf kecil.', 'Anda tahu bahwa 文字 berarti "huruf". Jadi, apa itu "huruf kecil"? Itu akan menjadi huruf kecil.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
