INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc18bddc-e14c-41ce-9808-fdd30144fe19', '冬休みに、かぞくで山の中のホテルにとまりました。', 'Selama liburan musim dingin, keluarga saya menginap di sebuah hotel di pegunungan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc18bddc-e14c-41ce-9808-fdd30144fe19', '冬休みは子どもたちがいえで兄弟げんかばっかりしていて大へんでした。', 'Liburan musim dingin cukup sulit karena anak-anak saya sering bertengkar di rumah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('cc18bddc-e14c-41ce-9808-fdd30144fe19', '冬休みは、毎日一日中ジョギングをしていました。', 'Selama liburan musim dingin, saya jogging setiap hari, sepanjang hari.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('852c7c14-8884-4b77-8c65-e27d6d23c724', 'vocabulary', '方言', '方言', 2, 'e5f6a7b8-c90d-1e2f-3a4b-5c6d7e8f9a0b', 'Cara Anda mengatakan sesuatu bisa diterjemahkan sebagai aksen Anda... tapi ini jauh lebih besar. Ini adalah keseluruhan "cara" berbicara. Ini adalah dialek. 
